hooks.command:
c=$(jq -r '.tool_input.command // empty'); [ -n "$c" ] || exit 0
say() { jq -n --arg d "$1" --arg r "$2" '{hookSpecificOutput:{hookEventName:"PreToolUse",permissionDecision:$d,permissionDecisionReason:$r}}'; exit 0; }
case "$c" in *"git add"*|*"git commit"*)
  bad=$({ printf '%s\n' "$c"; git diff --cached --name-only 2>/dev/null; } | grep -Ei 'Grouppoints\.png|ChatGPT Image|Summit-[^ ]*\.png' | head -3)
  [ -z "$bad" ] || say deny "Church content must never reach this public repo (CLAUDE.md). Matched: $bad -- unstage it with git restore --staged <file> and check .gitignore still covers it." ;;
esac
case "$c" in *golden.py*--record*)
  say ask "golden.py --record REWRITES golden.json wholesale and keeps only the jobs this run rendered; every job not rendered is silently dropped from the guard. Use --check unless re-recording is the intent." ;;
esac
case "$c" in *"python app.py"*|*"python3 app.py"*|*"python scripts/smoke.py"*|*"python3 scripts/smoke.py"*|"./run.sh"*|*"&& ./run.sh"*|*"; ./run.sh"*|*"sh run.sh"*)
  case "$c" in *SERVICE_VISUALS_STATS=0*) ;; *) say deny "Set SERVICE_VISUALS_STATS=0 outside a real release (CLAUDE.md) so this run stays out of the owner's analytics. run.sh sets neither this nor PORT -- use PORT=8799 SERVICE_VISUALS_STATS=0 .venv/bin/python app.py, or the service-visuals-dev preview config." ;; esac ;;
esac
case "$c" in *"python app.py"*|*"python3 app.py"*|"./run.sh"*|*"&& ./run.sh"*|*"; ./run.sh"*|*"sh run.sh"*)
  case "$c" in
    *PORT=8765*) say deny "Port 8765 is the owner's INSTALLED packaged app (CLAUDE.md). Use PORT=8799 for a source run." ;;
    *PORT=*) ;;
    *) say deny "app.py defaults to port 8765, which is the owner's INSTALLED app (CLAUDE.md). Pass PORT=8799 explicitly." ;;
  esac ;;
esac
exit 0

f=$(jq -r '.tool_response.filePath // .tool_input.file_path // empty')
case "$f" in
  */render/timer.py) m="Countdown output is byte-identical-guarded (CLAUDE.md). Before this ships: git archive HEAD's render/ into a temp package, render 6s classic/ring/bar old vs new, extract frames and cmp them -- then SERVICE_VISUALS_STATS=0 .venv/bin/python scripts/golden.py --check." ;;
  */render/*.py) m="A renderer changed. SERVICE_VISUALS_STATS=0 .venv/bin/python scripts/golden.py --check must pass before this ships (CLAUDE.md)." ;;
  *) exit 0 ;;
esac
jq -n --arg m "$m" '{hookSpecificOutput:{hookEventName:"PostToolUse",additionalContext:$m}}'
